	/*<BeginMethod Name="System.Void Infragistics.Controls.Charts.CategorySeriesRenderManager::SetCategoryShapeAppearance(System.Windows.Shapes.Shape, System.Boolean, System.Boolean, System.Boolean, System.Boolean)" />*/
	setCategoryShapeAppearance: function (shape, strokeOnly, fillOnly, extended, useOutline) {
		var main = this._actualRenderFill;
		if (useOutline) {
			main = this._actualRenderOutline;
		}
		if (fillOnly) {
			shape.__fill = main;
		} else {
			if (strokeOnly) {
				shape.__stroke = main;
			} else {
				shape.__fill = main;
				shape.__stroke = this._actualRenderOutline;
			}
			shape.strokeThickness(this._actualRenderThickness);
			shape.strokeDashArray(this._actualRenderDashArray);
			shape.strokeDashCap(this._actualRenderDashCap);
			if (extended) {
			}
		}
		shape.__opacity = this._actualRenderOpacity;
	}
	/*<EndMethod Name="System.Void Infragistics.Controls.Charts.CategorySeriesRenderManager::SetCategoryShapeAppearance(System.Windows.Shapes.Shape, System.Boolean, System.Boolean, System.Boolean, System.Boolean)" />*/
