	/*<BeginMethod Name=" Infragistics.Controls.Charts.CategorySeriesRenderManager::GetBucketBounds(System.Int32, System.Int32)" />*/
	getBucketBounds: function (count, bucket) {
		var size = this._bucketSize;
		var i0 = Math.min(bucket * size, count - 1);
		var i1 = Math.min(i0 + size - 1, count - 1);
		var ret = new Array(2);
		ret[0] = Math.min(i0 + this._firstBucket * size, count - 1);
		ret[1] = Math.min(i1 + this._firstBucket * size, count - 1);
		return ret;
	}
	/*<EndMethod Name=" Infragistics.Controls.Charts.CategorySeriesRenderManager::GetBucketBounds(System.Int32, System.Int32)" />*/
	,
	/*<BeginMethod Name="System.Void Infragistics.Controls.Charts.CategorySeriesRenderManager::ApplyHighlightingStyle(Infragistics.Controls.Charts.HighlightingInfo)" />*/
	applyHighlightingStyle: function (info) {
		if (info == null) {
			return;
		}
		var additionalBrightness = info.progress();
		additionalBrightness = additionalBrightness * 0.5;
		this._actualRenderFill = this.getBrightenedBrush(this._actualRenderFill, additionalBrightness);
		this._actualRenderOutline = this.getBrightenedBrush(this._actualRenderOutline, additionalBrightness);
	}
	/*<EndMethod Name="System.Void Infragistics.Controls.Charts.CategorySeriesRenderManager::ApplyHighlightingStyle(Infragistics.Controls.Charts.HighlightingInfo)" />*/
	,
	/*<BeginMethod Name="System.Windows.Media.Brush Infragistics.Controls.Charts.CategorySeriesRenderManager::GetBrightenedBrush(System.Windows.Media.Brush, System.Double)" />*/
	getBrightenedBrush: function (brush, additionalBrightness) {
		if (brush == null) {
			return brush;
		}
		return $.ig.BrushUtil.prototype.getLightened(brush, additionalBrightness);
	}
	/*<EndMethod Name="System.Windows.Media.Brush Infragistics.Controls.Charts.CategorySeriesRenderManager::GetBrightenedBrush(System.Windows.Media.Brush, System.Double)" />*/
	,
