	/*<BeginMethod Name="System.Void Infragistics.Controls.Charts.FinancialSeries::WindowRectChangedOverride(System.Windows.Rect, System.Windows.Rect)" />*/
	windowRectChangedOverride: function (oldWindowRect, newWindowRect) {
		this.financialView().bucketCalculator().calculateBuckets(this.resolution());
		this.renderSeries(false);
	}
	/*<EndMethod Name="System.Void Infragistics.Controls.Charts.FinancialSeries::WindowRectChangedOverride(System.Windows.Rect, System.Windows.Rect)" />*/
