	/*<BeginMethod Name="System.Void Infragistics.Controls.Charts.StackedSeriesBase::AutoGeneratedSeries_CollectionResetting(System.Object, System.EventArgs)" />*/
	autoGeneratedSeries_CollectionResetting: function (sender, e) {
		var en = this.autoGeneratedSeries().getEnumerator();
		while (en.moveNext()) {
			var series = en.current();
			if (this.stackedSeriesManager() != null && this.stackedSeriesManager().seriesLogical().contains(series)) {
				series.parentSeries(null);
				this.stackedSeriesManager().seriesLogical().remove(series);
			}
		}
	}
	/*<EndMethod Name="System.Void Infragistics.Controls.Charts.StackedSeriesBase::AutoGeneratedSeries_CollectionResetting(System.Object, System.EventArgs)" />*/
