/*<BeginType Name="Infragistics.Controls.Charts.Messaging.MessageChannel" />*/

$.ig.util.defType('MessageChannel_Spark', 'Object', {
	init: function () {
		this.__sendQueue = new $.ig.Array();
		$.ig.Object.prototype.init.call(this);
	},
	__sendQueue: null,
	/*<BeginMethod Name="System.Void Infragistics.Controls.Charts.Messaging.MessageChannel::SendMessage(Infragistics.Controls.Charts.Messaging.Message)" />*/
	sendMessage: function (message) {
		if (this.messageSent != null) {
			this.messageSent(message);
		} else {
			this.__sendQueue.push(message);
		}
	}
	/*<EndMethod Name="System.Void Infragistics.Controls.Charts.Messaging.MessageChannel::SendMessage(Infragistics.Controls.Charts.Messaging.Message)" />*/
	,
	/*<BeginMethod Name="System.Void Infragistics.Controls.Charts.Messaging.MessageChannel::AttachTarget(Infragistics.Controls.Charts.Messaging.MessageEventHandler)" />*/
	attachTarget: function (m) {
		this.messageSent = $.ig.Delegate.prototype.combine(this.messageSent, m);
		while (this.__sendQueue.length > 0) {
			var mess = this.__sendQueue.shift();
			this.messageSent(mess);
		}
	}
	/*<EndMethod Name="System.Void Infragistics.Controls.Charts.Messaging.MessageChannel::AttachTarget(Infragistics.Controls.Charts.Messaging.MessageEventHandler)" />*/
	,
	messageSent: null,
	/*<BeginMethod Name="System.Void Infragistics.Controls.Charts.Messaging.MessageChannel::DetachTarget(Infragistics.Controls.Charts.Messaging.MessageEventHandler)" />*/
	detachTarget: function (m) {
		this.messageSent = $.ig.Delegate.prototype.remove(this.messageSent, m);
	}
	/*<EndMethod Name="System.Void Infragistics.Controls.Charts.Messaging.MessageChannel::DetachTarget(Infragistics.Controls.Charts.Messaging.MessageEventHandler)" />*/
	,
	__connectedTo: null,
	/*<BeginMethod Name="System.Void Infragistics.Controls.Charts.Messaging.MessageChannel::ConnectTo(Infragistics.Controls.Charts.Messaging.MessageChannel)" />*/
	connectTo: function (m) {
		this.__connectedTo = m;
		this.attachTarget(this.sendToNext.runOn(this));
	}
	/*<EndMethod Name="System.Void Infragistics.Controls.Charts.Messaging.MessageChannel::ConnectTo(Infragistics.Controls.Charts.Messaging.MessageChannel)" />*/
	,
	/*<BeginMethod Name="System.Void Infragistics.Controls.Charts.Messaging.MessageChannel::DetachFromNext()" />*/
	detachFromNext: function () {
		if (this.__connectedTo == null) {
			return;
		}
		this.detachTarget(this.sendToNext.runOn(this));
		this.__connectedTo = null;
	}
	/*<EndMethod Name="System.Void Infragistics.Controls.Charts.Messaging.MessageChannel::DetachFromNext()" />*/
	,
	/*<BeginMethod Name="System.Void Infragistics.Controls.Charts.Messaging.MessageChannel::SendToNext(Infragistics.Controls.Charts.Messaging.Message)" />*/
	sendToNext: function (m) {
		if (this.__connectedTo != null) {
			this.__connectedTo.sendMessage(m);
		}
	}
	/*<EndMethod Name="System.Void Infragistics.Controls.Charts.Messaging.MessageChannel::SendToNext(Infragistics.Controls.Charts.Messaging.Message)" />*/
	,
	/*<BeginMethod Name="System.String Infragistics.Controls.Charts.Messaging.MessageChannel::ToString()" />*/
	toString: function () {
		return "MessageQueue";
	}
	/*<EndMethod Name="System.String Infragistics.Controls.Charts.Messaging.MessageChannel::ToString()" />*/
	,
	$type: new $.ig.Type('MessageChannel_Spark', $.ig.Object.prototype.$type)
}, true);

/*<EndType Name="Infragistics.Controls.Charts.Messaging.MessageChannel" />*/

